param([ValidateSet('RED','GREEN')][string]$Phase='GREEN',[string]$RepositoryRoot)
$ErrorActionPreference='Stop'
Import-Module (Join-Path $RepositoryRoot 'evals\lib\TestHarness.psm1') -Force
Import-Module (Join-Path $RepositoryRoot 'scripts\lib\ProjectFlightControl.Doctor.psm1') -Force
$results=New-Object System.Collections.Generic.List[object]
function Check([string]$id,[bool]$ok,[string]$message){$results.Add((New-PfcResult $id $(if($ok){'PASS'}else{'FAIL'}) $message))}
$root=Join-Path ([IO.Path]::GetTempPath()) ('pfc-unit-smoke-'+[guid]::NewGuid().ToString('N'));$fixture=Join-Path $root 'repo';$worktree=Join-Path $root 'worktree';$calls=New-Object System.Collections.Generic.List[string]
try {
    New-Item -ItemType Directory -Path $root -Force|Out-Null
    $proc={param($argv);$calls.Add(($argv -join ' '));$joined=$argv -join ' ';if($joined -match 'rev-parse HEAD'){return [pscustomobject]@{ExitCode=0;StdOut=('a'*40);StdErr=''}};if($joined -match 'symbolic-ref --short -q HEAD'){return [pscustomobject]@{ExitCode=1;StdOut='';StdErr=''}};return [pscustomobject]@{ExitCode=0;StdOut='';StdErr=''}}
    $wt={param($op,$payload);$calls.Add($op);if($op -eq 'create-fixture'){New-Item -ItemType Directory -Path $payload.root -Force|Out-Null;return [pscustomobject]@{status='PASS';path=$payload.root}};if($op -eq 'create-worktree'){New-Item -ItemType Directory -Path $payload.path -Force|Out-Null;return [pscustomobject]@{status='PASS';path=$payload.path;sha=$payload.sha;detached=$true}};if($op -eq 'remove-worktree'){if(Test-Path $payload.path){Remove-Item -LiteralPath $payload.path -Recurse -Force};return [pscustomobject]@{status='PASS';standard_remove=$true;operation='git worktree remove'}};return $null}
    $validSpecialist={param($order);if($order.PSObject.Properties['action']){$calls.Add([string]$order.action);return [pscustomobject]@{status='PASS'}};$report=[ordered]@{control_run_id='C';lease_epoch='1';goal_id='G';goal_version='1';milestone_id='M';milestone_contract_version='1';revision='0';sender_role='Specialist';recipient_role='Goalkeeper';created_at='now';status='FINDING';specialist_report_id='R';specialist_order_id='O';question='q';evidence_sha=$order.evidence_sha;finding='f';evidence='e';risk='r';recommendation='n';confidence='HIGH';diagnostics_run='none'};$report=[pscustomobject]$report;$txt=$report|ConvertTo-Json -Depth 20 -Compress;$hash=[BitConverter]::ToString(([Security.Cryptography.SHA256]::Create().ComputeHash([Text.Encoding]::UTF8.GetBytes($txt)))).Replace('-','').ToLowerInvariant();return [pscustomobject]@{read_only=$true;report=$report;report_sha256=$hash}}
    $invalidSpecialist={param($order);if($order.PSObject.Properties['action']){$calls.Add([string]$order.action);return [pscustomobject]@{status='PASS'}};return [pscustomobject]@{read_only=$false;report=[pscustomobject]@{schema='SPECIALIST_REPORT'}}}
    $missingSwitch=$false;try { Invoke-PfcSpecialistSmoke -RepositoryRoot $RepositoryRoot -UserHome $root -StateRoot $root -ProcessInvoker $proc -WorktreeAdapter $wt -SpecialistInvoker $validSpecialist | Out-Null } catch { $missingSwitch=$true };Check 'smoke.specialist-smoke-required' $missingSwitch 'switch is mandatory'
    $invoker=if($Phase -eq 'RED'){$invalidSpecialist}else{$validSpecialist}
    $record=Invoke-PfcSpecialistSmoke -SpecialistSmoke -RepositoryRoot $RepositoryRoot -UserHome $root -StateRoot $root -ProcessInvoker $proc -WorktreeAdapter $wt -SpecialistInvoker $invoker
    if($Phase -eq 'RED') {
        Check 'smoke.red-exposes-read-only-gap' ($record.status -eq 'AVAILABLE') ('status='+$record.status+'; reason='+$record.invalidation_reason)
    } else {
        Check 'smoke.fixture-created' ($calls -contains 'create-fixture') 'fixture repo created'
        Check 'smoke.fixed-sha-worktree' ($record.sha -eq 'VALID' -and $calls -contains 'create-worktree') 'fixed SHA worktree'
        Check 'smoke.read-only-order-schema' ($record.report -eq 'PASS') 'read-only order and structured report'
        Check 'smoke.tracked-staged-before-after' (($calls -match 'status') -and ($calls -match 'diff --cached')) 'tracked/staged checks'
        Check 'smoke.report-sha-verified' (-not [string]::IsNullOrWhiteSpace([string]$record.report_sha256)) 'report SHA'
        Check 'smoke.close-process' ($calls -contains 'close') 'close process'
        Check 'smoke.standard-worktree-remove' ($calls -contains 'remove-worktree') 'standard worktree remove'
        Check 'smoke.available-only-on-full-proof' ($record.status -eq 'AVAILABLE' -and $record.specialist_capability -eq 'AVAILABLE') 'AVAILABLE requires all invariants'
        $failed=Invoke-PfcSpecialistSmoke -SpecialistSmoke -RepositoryRoot $RepositoryRoot -UserHome $root -StateRoot $root -ProcessInvoker $proc -WorktreeAdapter $wt -SpecialistInvoker $invalidSpecialist
        Check 'smoke.failure-invalidates-available' ($failed.status -eq 'UNKNOWN' -and $failed.invalidation_reason) ('status='+$failed.status)
        $crossBranchSpecialist={param($order);if($order.PSObject.Properties['action']){$calls.Add([string]$order.action);return [pscustomobject]@{status='PASS'}};$report=[ordered]@{control_run_id='C';lease_epoch='1';goal_id='G';goal_version='1';milestone_id='M';milestone_contract_version='1';revision='0';sender_role='Specialist';recipient_role='Goalkeeper';created_at='now';status='FINDING';specialist_report_id='R';specialist_order_id='O';question='q';evidence_sha=$order.evidence_sha;finding='f';evidence='e';risk='r';recommendation='n';confidence='HIGH';diagnostics_run='none';missing_evidence='cross-branch'};$report=[pscustomobject]$report;$txt=$report|ConvertTo-Json -Depth 20 -Compress;$hash=[BitConverter]::ToString(([Security.Cryptography.SHA256]::Create().ComputeHash([Text.Encoding]::UTF8.GetBytes($txt)))).Replace('-','').ToLowerInvariant();return [pscustomobject]@{read_only=$true;report=$report;report_sha256=$hash}}
        $crossBranch=Invoke-PfcSpecialistSmoke -SpecialistSmoke -RepositoryRoot $RepositoryRoot -UserHome $root -StateRoot $root -ProcessInvoker $proc -WorktreeAdapter $wt -SpecialistInvoker $crossBranchSpecialist
        Check 'smoke.finding-cross-branch-field-invalid' ($crossBranch.status -eq 'UNKNOWN' -and $crossBranch.invalidation_reason -eq 'structured-report-additional-property') ('status='+$crossBranch.status+';reason='+$crossBranch.invalidation_reason)
        $branchWt={param($op,$payload);if($op -eq 'create-fixture'){New-Item -ItemType Directory -Path $payload.root -Force|Out-Null;return [pscustomobject]@{status='PASS'}};if($op -eq 'create-worktree'){New-Item -ItemType Directory -Path $payload.path -Force|Out-Null;return [pscustomobject]@{status='PASS';detached=$false}};if($op -eq 'remove-worktree'){if(Test-Path $payload.path){Remove-Item -LiteralPath $payload.path -Recurse -Force};return [pscustomobject]@{status='PASS';standard_remove=$true}}}
        $branch=Invoke-PfcSpecialistSmoke -SpecialistSmoke -RepositoryRoot $RepositoryRoot -UserHome $root -StateRoot $root -ProcessInvoker $proc -WorktreeAdapter $branchWt -SpecialistInvoker $validSpecialist
        Check 'smoke.branch-attached-worktree-invalid' ($branch.status -eq 'UNKNOWN' -and $branch.invalidation_reason -eq 'worktree-detached-proof-missing') ('status='+$branch.status+';reason='+$branch.invalidation_reason)
        $fakeRemoveWt={param($op,$payload);if($op -eq 'create-fixture'){New-Item -ItemType Directory -Path $payload.root -Force|Out-Null;return [pscustomobject]@{status='PASS'}};if($op -eq 'create-worktree'){New-Item -ItemType Directory -Path $payload.path -Force|Out-Null;return [pscustomobject]@{status='PASS';detached=$true}};if($op -eq 'remove-worktree'){if(Test-Path $payload.path){Remove-Item -LiteralPath $payload.path -Recurse -Force};return [pscustomobject]@{status='PASS'}}}
        $fakeRemove=Invoke-PfcSpecialistSmoke -SpecialistSmoke -RepositoryRoot $RepositoryRoot -UserHome $root -StateRoot $root -ProcessInvoker $proc -WorktreeAdapter $fakeRemoveWt -SpecialistInvoker $validSpecialist
        Check 'smoke.fake-remove-item-invalid' ($fakeRemove.status -eq 'UNKNOWN' -and $fakeRemove.invalidation_reason -eq 'standard-worktree-remove-proof-missing') ('status='+$fakeRemove.status+';reason='+$fakeRemove.invalidation_reason)
    }
} catch { $results.Add((New-PfcResult 'smoke.failure' 'FAIL' $_.Exception.Message)) } finally { if(Test-Path $root){Remove-Item -LiteralPath $root -Recurse -Force} }
return $results.ToArray()
